using System.Reflection;using System.Text.Json;using SkiaSharp;using ValveResourceFormat;using ValveResourceFormat.ResourceTypes;
internal static class EditorTextureSurfaceTests{
 internal static void Run(string dir,MethodInfo run){
  var flagsType=typeof(Texture).GetProperty("Flags")!.PropertyType;var extraType=typeof(Texture).GetProperty("ExtraData")!.PropertyType.GenericTypeArguments[0];int cube=Convert.ToInt32(Enum.Parse(flagsType,"CUBE_TEXTURE")),volume=Convert.ToInt32(Enum.Parse(flagsType,"VOLUME_TEXTURE"));uint sheet=Convert.ToUInt32(Enum.Parse(extraType,"SHEET"));
  var png=Path.Combine(dir,"surface.png");using(var bitmap=new SKBitmap(2,2,SKColorType.Rgba8888,SKAlphaType.Unpremul)){bitmap.Erase(new SKColor(90,100,200,17));using var image=SKImage.FromBitmap(bitmap);using var encoded=image.Encode(SKEncodedImageFormat.Png,100);File.WriteAllBytes(png,encoded.ToArray());}
  foreach(var c in new[]{(Name:"sheet",Flags:0,Depth:1,Sheet:true),(Name:"cube",Flags:cube,Depth:2,Sheet:false),(Name:"volume",Flags:volume,Depth:4,Sheet:false),(Name:"array",Flags:0,Depth:3,Sheet:false)}){
   int faces=c.Name=="cube"?6:1;string input=Path.Combine(dir,c.Name+".vtex_c"),output=Path.Combine(dir,c.Name+"-edited.vtex_c"),manifest=Path.Combine(dir,c.Name+".json");int size=c.Sheet?60:40;
   using(var stream=File.Create(input))using(var w=new BinaryWriter(stream)){w.Write((uint)(28+size));w.Write((ushort)12);w.Write((ushort)1);w.Write(8u);w.Write(1u);w.Write(System.Text.Encoding.ASCII.GetBytes("DATA"));w.Write(8u);w.Write((uint)size);w.Write((ushort)1);w.Write((ushort)c.Flags);for(int i=0;i<4;i++)w.Write(0f);w.Write((ushort)2);w.Write((ushort)2);w.Write((ushort)c.Depth);w.Write((byte)4);w.Write((byte)1);w.Write(0u);w.Write(c.Sheet?8u:0u);w.Write(c.Sheet?1u:0u);if(c.Sheet){w.Write(sheet);w.Write(8u);w.Write(8u);w.Write(8u);w.Write(0u);}for(int surface=0;surface<faces*c.Depth;surface++)for(int i=0;i<4;i++){w.Write((byte)(surface+1));w.Write((byte)20);w.Write((byte)30);w.Write((byte)19);}}
   int layer=c.Depth-1,face=faces-1;File.WriteAllText(manifest,JsonSerializer.Serialize(new{input,output,image=png,layer,face}));run.Invoke(null,new object[]{manifest});using var result=new Resource{FileName=output};result.Read(output);var texture=(Texture)result.DataBlock!;if(texture.Depth!=c.Depth||(int)texture.Flags!=c.Flags)throw new Exception("Lost surface layout");for(uint z=0;z<c.Depth;z++)for(int f=0;f<faces;f++){using var bitmap=texture.GenerateBitmap(z,(Texture.CubemapFace)f);var pixel=bitmap.GetPixel(0,0);if(z==layer&&f==face){if(pixel.Red!=90||pixel.Alpha!=17)throw new Exception("Edited surface mismatch");}else if(pixel.Red!=z*faces+f+1||pixel.Alpha!=19)throw new Exception("Untouched surface changed");}if(c.Sheet&&(texture.GetSpriteSheetData() is null||texture.ExtraData.Values.All(v=>!v.SequenceEqual(new byte[]{8,0,0,0,0,0,0,0}))))throw new Exception("Sheet metadata lost");if(c.Name=="cube"){var many=Path.Combine(dir,"cube-many.vtex_c");File.WriteAllText(manifest,JsonSerializer.Serialize(new{input,output=many,images=new[]{new{image=png,layer=0,face=0},new{image=png,layer=c.Depth-1,face=faces-1}}}));run.Invoke(null,new object[]{manifest});using var multiple=new Resource{FileName=many};multiple.Read(many);var mt=(Texture)multiple.DataBlock!;using var a=mt.GenerateBitmap();using var b=mt.GenerateBitmap((uint)(c.Depth-1),(Texture.CubemapFace)(faces-1));if(a.GetPixel(0,0).Alpha!=17||b.GetPixel(0,0).Red!=90)throw new Exception("Multiple edited surfaces lost");}
  }
  Console.WriteLine("Texture surface tests passed: sprite sheet metadata, cube array faces, volume slices and untouched alpha.");
 }
}
